    assertSignatureFail("array()");
    assertSignatureFail("map()");
    assertSignatureFail("x", ImmutableSet.of("x"));

    // ensure this is not treated as a row type
    assertSignature("rowxxx(a)", "rowxxx", ImmutableList.of("a"));
}

