                                                    tableScan(
                                                            equalTo(elasticsearchTableHandle.withColumns(Set.of(column1Handle))),
                                                            TupleDomain.all(),
                                                            ImmutableMap.of("s_expr_1", equalTo(column1Handle)))))))));
    deleteIndex(tableName);
