    assertThat(assertions.expression("a not like 'm____y'")
            .binding("a", "'monkey'"))
            .isEqualTo(false);

    assertThat(assertions.expression("a not like 'lion'")
            .binding("a", "'monkey'"))
            .isEqualTo(true);

    assertThat(assertions.expression("a not like 'monkey'")
            .binding("a", "null"))
            .isNull(BOOLEAN);

    assertThat(assertions.expression("a not like null")
            .binding("a", "'monkey'"))
