    assertEquals(1, observerPairs.size());

    // Different listener
    observerPairs.remove(ONE, new TestListener());
    assertEquals(1, observerPairs.size());

    // Should remove now
    observerPairs.remove(ONE, testListener);
    assertEquals(0, observerPairs.size());
}

