    assertQuery("SELECT * FROM " + tableName, "VALUES 1");
    assertUpdate("INSERT INTO " + tableName + " VALUES 2", 1);
    assertQuery("SELECT * FROM " + tableName, "VALUES (1), (2)");

    assertUpdate("DROP TABLE " + tableName);
}

