            .isFullyPushedDown();
    // Test queries with no grouping columns
    assertThat(query("SELECT COUNT(DISTINCT string_col) FROM " + ALL_TYPES_TABLE))
            .isFullyPushedDown();
    assertThat(query("SELECT COUNT(DISTINCT bool_col) FROM " + ALL_TYPES_TABLE))
