    assertThat(query("select \"date\" from \"select \"\"qu\"\"\"\"ot\"\"\"\"ed\"\" as \"\"date\"\" from quotes_in_column_name\""))
            .matches("VALUES (VARCHAR 'FOO'), (VARCHAR 'BAR')")
