public void testInSubquery()
{
    // zero sample
    assertThat(assertions.query("SELECT count(*) FROM tpch.tiny.orders WHERE orderkey IN (SELECT orderkey FROM tpch.tiny.orders TABLESAMPLE BERNOULLI (0))"))
            .matches("VALUES BIGINT '0'");

