	// and won't restore TLs from the Context when contextWrite operator is
	// missing along the way in the chain.
	assertThreadLocalsPresent(
			Flux.just("Hello")
			    .withLatestFrom(threadSwitchingFlux(), (s1, s2) -> s1));
}

