      int i4 = Math.max(j, k);
      long randValue = TestUtils.randValue(-1000, 1000);
      st.rangeUpdate1(i3, i4, randValue);
      bruteForceAssignRangeUpdate(ar, i3, i4, randValue);
    }
  }
}

