  retryPolicy = struct.getStruct().retryPolicy();
  assertThat(retryPolicy.initialBackoff()).isEqualTo(Durations.fromMillis(25));
  assertThat(retryPolicy.maxBackoff()).isEqualTo(Durations.fromMillis(250));

