    for (TestAccessMode am : testAccessModesOfType(TestAccessType.GET_AND_SET)) {
        checkNPE(() -> { // null receiver
            float x = (float) hs.get(am, methodType(float.class, VarHandleTestMethodTypeFloat.class, float.class)).
