        int x = (int) vh.get();
        assertEquals(x, (int)(0x01234567 | 0x89ABCDEF), "getAndBitwiseOrRelease int value");
    }

    // get and bitwise and
    {
        vh.set(0x01234567);

        int o = (int) vh.getAndBitwiseAnd(0x89ABCDEF);
        assertEquals(o, 0x01234567, "getAndBitwiseAnd int");
