public void childCycle_reduces() {
  Node zero = new Node(0);
  Node one = new Node(0);
  Node two = new Node(0);
  Node three = new Node(0);
  Node four = new Node(0);
  Node five = new Node(0);

  // The example consists of one cycle hanging off from another one.
  // 0 -> 1 -> 2 -> 0
  zero.left = one;
  one.left = two;
  two.left = zero;
  // 1 -> 3 -> 4 -> 5 -> 3
  one.right = three;
  three.left = four;
  four.left = five;
  five.left = three;

  assertThat(computeBreakdown(zero))
      .isEqualTo(
          new Breakdown(
              ImmutableMap.of(),
              ImmutableSet.of(
                  ImmutableSet.of(zero),
                  ImmutableSet.of(one),
                  ImmutableSet.of(two),
                  ImmutableSet.of(three, four, five))));
}

