        } catch (IllegalArgumentException ex) {
            System.out.println("OK: "+ex);
        }
    }
    // Sizes not in the above array are good:
    for (int i = 1; i <= 10; ++i) {
        target.asCollector(0, Object[].class, minbig - i);
    }
}

