public static void testLongProductsOverflowOnceAtMax(boolean flag, boolean flag2) {
    // 88971434439113593 * 311 = Long.MAX_VALUE*3 + 2 --cast to long--> Long.MAX_VALUE
    long l = flag ? 88971434439113592L : 88971434439113593L;
    int x = flag2 ? 310 : 311;

