private static void test2(int[] dst, int[] src) {
    // Partial peel is applied. Some side effect between exit and
    // safepoint.
    int v = src[0];
    for (int i = 0; ; ) {
        synchronized (new Object()) {}
        dst[i] = v;
        i++;
        if (i >= src.length) {
            break;
        }
        v = src[i];
        if (i / 2 >= 2000) {
            break;
        }
    }
}

